import sys
from collections import defaultdict, deque

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    m = int(input[1])
    flights = [(int(input[2 + 2 * i]), int(input[3 + 2 * i])) for i in range(m)]

    graph = defaultdict(list)
    for a, b in flights:
        graph[a].append(b)

    dist = [-1] * (n + 1)
    dist[1] = 0
    queue = deque([1])

    while queue:
        u = queue.popleft()
        for v in graph[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                queue.append(v)

    if dist[n] == -1:
        print("No")
        return

    def dfs(u, d):
        if u == n:
            return True
        for v in graph[u]:
            if dist[v] == d + 1:
                if dfs(v, d + 1):
                    return True
        return False

    def assign_durations(u, d):
        for v in graph[u]:
            if dist[v] == d + (2 if dfs(v, d + 1) else 1):
                durations[flights.index((u, v))] = 2 if dfs(v, d + 1) else 1
                assign_durations(v, d + (2 if dfs(v, d + 1) else 2))

    durations = [0] * m
    assign_durations(1, 0)

    if any(d == 0 for d in durations):
        print("No")
    else:
        print("Yes")
        print("\n".join(map(str, durations)))

main()
